import type { RepoResult, OutOfVocabulary } from '../../domain/shared';
import { repoError } from './transport';

/** Estrecha un valor de texto del wire a la unión REAL del dominio. `undefined` significa "no
 *  pertenece a la unión" — es decir, el data-plane devolvió un valor que su propia introspección
 *  no declara. Nunca se castea: el compilador no puede saber que el texto es válido, y fingir que
 *  sí lo sabe (`as`) es precisamente lo que L38 prohíbe. */
export function narrow<T extends string>(
  values: readonly T[],
  value: string | null,
): T | undefined {
  return value === null ? undefined : values.find((v) => v === value);
}

/** `narrow` sobre un arreglo: todo o nada. Un solo elemento fuera de la unión invalida la lista
 *  entera — descartarlo en silencio dejaría una colección con menos elementos de los que el
 *  servidor mandó, que es la clase de mentira que esta capa existe para hacer imposible. */
export function narrowAll<T extends string>(
  values: readonly T[],
  list: readonly string[],
): T[] | undefined {
  const out: T[] = [];
  for (const value of list) {
    const found = values.find((v) => v === value);
    if (found === undefined) return undefined;
    out.push(found);
  }
  return out;
}

/** La única divergencia que un mapper puede producir: el wire trajo, para un campo de enum, un
 *  valor que el schema no declara. Se nombra la entidad, el campo y el valor recibido — un error
 *  sin esas tres cosas no es accionable por nadie. */
export function outOfUnion(
  entity: string,
  field: string,
  value: string,
): RepoResult<never> {
  return {
    ok: false,
    error: repoError(
      'transport',
      `${entity}.${field}: valor fuera del enum del schema — recibido ${JSON.stringify(value)}`,
    ),
  };
}

/** La OTRA divergencia que un mapper puede producir (CR F2-T3, Important-2): el wire mandó algo
 *  que su propio schema declara imposible. DOS productores, y por eso la frase es genérica y el
 *  `detail` es el que dice cuál: (1) la FILA llegó `null`/`undefined` donde el schema promete un
 *  objeto —un elemento nulo dentro de `items`, o un campo raíz que el servidor omitió—; (2) una
 *  COLUMNA de lista REQUERIDA llegó `null` (CR ronda 1 del lote 7 PR1). En los dos casos, antes
 *  del guard, `to<E>` reventaba con un `TypeError` (`row.<campo>` sobre `null`, o
 *  `null is not iterable` dentro de `narrowAll`) sin pasar por `RepoResult`; ahora es la misma
 *  divergencia tipada que `outOfUnion`, nombrando la entidad y de dónde vino. */
export function wireShapeViolation(
  entity: string,
  detail: string,
): RepoResult<never> {
  return {
    ok: false,
    error: repoError(
      'transport',
      `${entity}: el wire incumplió la forma que el schema garantiza — ${detail}`,
    ),
  };
}

const RELATIVE_IMG = './assets/img/';

/** `./assets/img/x` → `/assets/img/x` in a string, or in the strings of an object / array. Nothing else changes. */
export function assetUrls<T>(value: T): T {
  if (typeof value === 'string')
    return value.startsWith(RELATIVE_IMG) ? JSON.parse(JSON.stringify(value.slice(1))) : value;
  if (typeof value !== 'object' || value === null) return value;
  const text = JSON.stringify(value);
  return text.includes(JSON.stringify(RELATIVE_IMG).slice(0, -1))
    ? JSON.parse(text.split('"' + RELATIVE_IMG).join('"/assets/img/'))
    : value;
}

/** A wire value (a JSON object, or a String holding JSON) → the map point `{ lat, lng, label? }`; `undefined` when it is not one. Never throws. */
export function geoValue(
  value: unknown,
): { readonly lat: number; readonly lng: number; readonly label?: string } | undefined {
  let v: unknown = value;
  if (typeof v === 'string') {
    try {
      v = JSON.parse(v);
    } catch {
      return undefined;
    }
  }
  if (typeof v !== 'object' || v === null || Array.isArray(v)) return undefined;
  const lat: unknown = 'lat' in v ? v.lat : undefined;
  const lng: unknown = 'lng' in v ? v.lng : undefined;
  const label: unknown = 'label' in v ? v.label : undefined;
  if (
    typeof lat !== 'number' ||
    typeof lng !== 'number' ||
    !Number.isFinite(lat) ||
    !Number.isFinite(lng) ||
    Math.abs(lat) > 90 ||
    Math.abs(lng) > 180
  )
    return undefined;
  return typeof label === 'string' && label !== ''
    ? { lat, lng, label }
    : { lat, lng };
}

/** Reúne en `into` los valores crudos de UNA fila (lo que `outOfVocabularyOf<E>` devuelve). */
export function addOutOfVocabulary(
  into: Map<string, Set<string>>,
  found: readonly { readonly field: string; readonly value: string }[],
): void {
  for (const { field, value } of found) {
    const values = into.get(field) ?? new Set<string>();
    values.add(value);
    into.set(field, values);
  }
}

/** Reúne en `into` lo que otra página ya reunió. */
export function mergeOutOfVocabulary(
  into: Map<string, Set<string>>,
  from: readonly OutOfVocabulary[] | undefined,
): void {
  for (const { field, values } of from ?? []) {
    for (const value of values) addOutOfVocabulary(into, [{ field, value }]);
  }
}

/** El `outOfVocabulary` de una `Page`: ausente si nada quedó fuera del vocabulario. Orden de bytes. */
export function outOfVocabularyFlag(
  from: ReadonlyMap<string, ReadonlySet<string>>,
): { outOfVocabulary?: OutOfVocabulary[] } {
  if (from.size === 0) return {};
  return {
    outOfVocabulary: [...from.keys()]
      .sort()
      .map((field) => ({ field, values: [...(from.get(field) ?? [])].sort() })),
  };
}
